insert into public.cs_lessons(id,position,title,description,reading,minutes,xp,journey_id,journey_position,reading_cards,checklist,sources,reviewed_at) values ('uni-food',300,'Plan a food shop','Practise fitting a shopping list into a weekly amount.','Practice example: Alex has £35 for food this week. A planned shop costs £27, leaving £8. These are made-up figures, not a suggested food budget. A short list can help you remember what you need. In this example, Alex checks the cupboard before buying another bag of rice. A bigger packet does not always cost less per unit. Compare the price for the same amount, and consider whether you will use it all.',3,30,'university',5,'["Practice example: Alex has £35 for food this week. A planned shop costs £27, leaving £8. These are made-up figures, not a suggested food budget.", "A short list can help you remember what you need. In this example, Alex checks the cupboard before buying another bag of rice.", "A bigger packet does not always cost less per unit. Compare the price for the same amount, and consider whether you will use it all."]'::jsonb,'["Try the example calculation with your own notes."]'::jsonb,'[]'::jsonb,null) on conflict (id) do nothing;
insert into public.cs_lessons(id,position,title,description,reading,minutes,xp,journey_id,journey_position,reading_cards,checklist,sources,reviewed_at) values ('uni-split',301,'Split shared costs clearly','Practise dividing a bill with housemates.','Practice example: three housemates agree to split a £60 shared purchase equally. Each person contributes £20. Before buying something together, agree what is shared, the amount and who will pay. A simple written note can help everyone remember the agreement. If someone cannot pay their share, discuss it before the payment date. Do not assume another person has agreed to cover it.',3,30,'university',6,'["Practice example: three housemates agree to split a £60 shared purchase equally. Each person contributes £20.", "Before buying something together, agree what is shared, the amount and who will pay. A simple written note can help everyone remember the agreement.", "If someone cannot pay their share, discuss it before the payment date. Do not assume another person has agreed to cover it."]'::jsonb,'["Try the example calculation with your own notes."]'::jsonb,'[]'::jsonb,null) on conflict (id) do nothing;
insert into public.cs_lessons(id,position,title,description,reading,minutes,xp,journey_id,journey_position,reading_cards,checklist,sources,reviewed_at) values ('uni-surprise',302,'Adjust for an unexpected cost','Practise changing a plan when something comes up.','Practice example: Taylor planned £40 of optional spending. A £15 replacement charger is needed. Using £15 from that amount leaves £25 for the original plans. A spending plan can change. Write down the new cost and check which planned spending can wait rather than counting the same money twice. If the example budget does not balance, pause and revise it. Completing this lesson does not mean you need to follow these particular amounts.',3,30,'university',7,'["Practice example: Taylor planned £40 of optional spending. A £15 replacement charger is needed. Using £15 from that amount leaves £25 for the original plans.", "A spending plan can change. Write down the new cost and check which planned spending can wait rather than counting the same money twice.", "If the example budget does not balance, pause and revise it. Completing this lesson does not mean you need to follow these particular amounts."]'::jsonb,'["Try the example calculation with your own notes."]'::jsonb,'[]'::jsonb,null) on conflict (id) do nothing;
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values ('uni-food-1','uni-food',1,'Alex has £35 and spends £27. How much remains?','["£8", "£12", "£27"]'::jsonb,0,'£35 minus £27 leaves £8.') on conflict (id) do nothing;
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values ('uni-food-2','uni-food',2,'What can Alex do before shopping?','["Buy everything again", "Check what is already in the cupboard", "Ignore the shopping list"]'::jsonb,1,'Checking what is already there can prevent duplicate purchases.') on conflict (id) do nothing;
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values ('uni-food-3','uni-food',3,'Which is cheaper per kilogram?','["500g for £2", "1kg for £5", "1kg for £3"]'::jsonb,2,'500g for £2 is £4 per kilogram. £3 per kilogram is the lowest of these example prices.') on conflict (id) do nothing;
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values ('uni-split-1','uni-split',1,'Three people split £60 equally. What is each share?','["£10", "£20", "£30"]'::jsonb,1,'£60 divided by three is £20.') on conflict (id) do nothing;
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values ('uni-split-2','uni-split',2,'What should the housemates agree before buying?','["Only the colour of the receipt", "Nothing until afterwards", "The cost and each person’s share"]'::jsonb,2,'Agreeing the cost and shares first makes expectations clear.') on conflict (id) do nothing;
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values ('uni-split-3','uni-split',3,'A person expects to miss the agreed payment date. What helps?','["Tell the others early and discuss it", "Say nothing", "Assume someone else will pay"]'::jsonb,0,'An early conversation gives everyone time to discuss the situation.') on conflict (id) do nothing;
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values ('uni-surprise-1','uni-surprise',1,'Taylor starts with £40 and uses £15 for a charger. What remains?','["£55", "£25", "£15"]'::jsonb,1,'£40 minus £15 leaves £25.') on conflict (id) do nothing;
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values ('uni-surprise-2','uni-surprise',2,'What should change when the new cost is added?','["Nothing", "Count the £15 twice", "Update the amount left for other spending"]'::jsonb,2,'The same £15 cannot also be spent on the original plans.') on conflict (id) do nothing;
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values ('uni-surprise-3','uni-surprise',3,'Which describes a useful practice budget?','["A plan you can update", "A promise never to change anything", "A list that ignores new costs"]'::jsonb,0,'A plan is useful when you can revise it as circumstances change.') on conflict (id) do nothing;
